// 2. Summarize the sample.
s, err := chartframe.Describe(values)
if err != nil { panic(err) }
fmt.Printf("Count: %d\nMean: %.2f\nMedian: %.2f\nQ1: %.2f\nQ3: %.2f\nMin: %.2f\nMax: %.2f\n", s.Count, s.Mean, s.Median, s.Q1, s.Q3, s.Min, s.Max)
if len(values) > 1 {
	ss := 0.0
	for _, v := range values { ss += (v-s.Mean)*(v-s.Mean) }
	fmt.Printf("Sample SD (n-1): %.2f\n", math.Sqrt(ss/float64(len(values)-1)))
} else { fmt.Println("Sample SD: requires at least two observations") }

// 3. Inspect the spread visually.
err = chartframe.New("Sample distribution").Labels("Sample", "Value").Box("observations", values).Save("sample-summary.svg")
if err != nil { panic(err) }
